for f in files:
    d=json.load(open(f))
    if isinstance(d,dict): d=[d]
    for rec in d:
        ev=rec.get('events',[])
        td=snap=prompt=side=tooluse=toolres=srcTool=think=0
        seen_tool_ids=set(); res_ids=set()
        for e in ev:
            r=(e.get('payload') or {}).get('raw') or {}
            t=r.get('type')
            if t=='system' and r.get('subtype')=='turn_duration': td+=1
            if t=='file-history-snapshot': snap+=1
            if r.get('isSidechain'): side+=1
            m=r.get('message') or {}
            if t=='user':
                c=m.get('content')
                blocks=c if isinstance(c,list) else []
                has_tr=any(isinstance(b,dict) and b.get('type')=='tool_result' for b in blocks)
                if has_tr:
                    toolres+=1
                    for b in blocks:
                        if isinstance(b,dict) and b.get('type')=='tool_result': res_ids.add(b.get('tool_use_id'))
                elif not r.get('isMeta'): prompt+=1
                if 'sourceToolAssistantUUID' in r: srcTool+=1
            if t=='assistant':
                for b in (m.get('content') or []) if isinstance(m.get('content'),list) else []:
                    if isinstance(b,dict):
                        if b.get('type')=='tool_use': tooluse+=1; seen_tool_ids.add(b.get('id'))
                        if b.get('type')=='thinking': think+=1
                u=m.get('usage') or {}
                if u: usage_in[u.get('input_tokens')]+=1
                if 'stop_reason' in m: stopr[m.get('stop_reason')]+=1
