import json,glob,collections
tot=collections.Counter()
for f in sorted(glob.glob('*.jsonl')):
    recs=[json.loads(l) for l in open(f) if l.strip()]
    byuuid={r['uuid']:r for r in recs if r.get('uuid')}
    # (b) sourceToolAssistantUUID -> promptId
    src={}
    for r in recs:
        if r.get('sourceToolAssistantUUID'): src[r['sourceToolAssistantUUID']]=r.get('promptId')
    # (a) positional carry-forward
    pos={}; cur=None
    for r in recs:
        if r.get('promptId'): cur=r['promptId']
        if r.get('type')=='assistant': pos[r['uuid']]=cur
    # (c) parentUuid chain walk up to a record carrying promptId
    def walk(r):
        seen=set(); n=r
        while n is not None:
            if n.get('promptId'): return n['promptId']
            p=n.get('parentUuid')
            if p is None or p in seen: return None
            seen.add(p); n=byuuid.get(p)
        return None
    chain={r['uuid']:walk(r) for r in recs if r.get('type')=='assistant'}
    A=set(pos)
    for u in A:
        a,b,c = pos[u], src.get(u), chain[u]
        tot['assistants']+=1
