def _op_path(ctx: _Ctx, op: dict, prev: Any) -> list[Node]:
    """Shortest path over the undirected `contain` edges within one graph (BFS)."""
    a = _one(ctx, op.get("a"), prev, pick="first")
    b_node = _one(ctx, op.get("b"), prev, pick="last")
    if a is None or b_node is None:
        return []
    target = b_node.id
    frontier: list[list[str]] = [[a.id]]
    seen = {a.id}
    while frontier:
        route = frontier.pop(0)
        tail = route[-1]
        if tail == target:
            return [ctx.nodes[i] for i in route]
        node = ctx.nodes.get(tail)
        if node is None:
            continue
        neigh = [c for c in node.children]
        parent = ctx.parent_of.get(tail)
        if parent is not None:
            neigh.append(parent)
        for nb in neigh:
            if nb not in seen and nb in ctx.nodes:
                seen.add(nb)
                frontier.append(route + [nb])
    return []


